INSERT INTO HUNTTECH_AI_FUNCTION_CONFIGURATION ( ID, VERSION, CREATE_TS, CREATED_BY, CODE, NAME, DESCRIPTION, CAPABILITY, SYSTEM_PROMPT, PROMPT_TEMPLATE, TEMPERATURE, MAX_TOKENS, EXECUTION_POLICY, FALLBACK_POLICY, ALLOW_MODEL_OVERRIDE, IS_ACTIVE, CONFIGURATION_VERSION ) SELECT '2f9176ea-6e73-4bca-91ae-9a6f73ca2a81'::uuid, 1, CURRENT_TIMESTAMP, 'migration', 'PROJECT_DESCRIPTION_GENERATE', 'Обработка загруженного описания проекта', 'Автоматическая обработка текста, загруженного во вкладке «Описание проекта» ProjectEdit', 'DOCUMENT_ANALYSIS', 'Ты анализируешь исходное описание проекта для HRM HuntTech. Сформируй точное структурированное описание без выдуманных фактов. Сохрани технологии, роли, ограничения и предметную область. Не используй чувствительные характеристики людей. Верни только итоговый обычный текст без Markdown и HTML.', 'Наименование проекта: ${projectName}
Имя загруженного файла: ${sourceFileName}

Исходный текст:
${sourceText}', 0.2, 3000, 'USER_OVERRIDE_ALLOWED', 'FALLBACK_TO_ADMIN', FALSE, TRUE, 1 WHERE NOT EXISTS ( SELECT 1 FROM HUNTTECH_AI_FUNCTION_CONFIGURATION WHERE CODE = 'PROJECT_DESCRIPTION_GENERATE' );
